#include <iostream>
#include <string>
#include <chrono>

enum class VehicleType { CAR, BIKE, TRUCK };

std::string vehicleTypeToString(VehicleType type) {
    switch (type) {
        case VehicleType::CAR: return "CAR";
        case VehicleType::BIKE: return "BIKE";
        case VehicleType::TRUCK: return "TRUCK";
    }
    return "UNKNOWN";
}

class Vehicle {
public:
    std::string plate;
    VehicleType type;

    Vehicle(std::string plate, VehicleType type) : plate(plate), type(type) {}
};

class Spot {
public:
    int id;
    bool free;
    VehicleType fits;

    Spot(int id, VehicleType fits) : id(id), free(true), fits(fits) {}
};

class Ticket {
public:
    std::string id;
    Vehicle vehicle;
    Spot spot;
    long long entryTime;

    Ticket(std::string id, Vehicle vehicle, Spot spot, long long entryTime)
        : id(id), vehicle(vehicle), spot(spot), entryTime(entryTime) {}
};

int main() {
    Vehicle car("KA-01-HH-1234", VehicleType::CAR);
    Spot spot(101, VehicleType::CAR);
    long long entryTime = std::chrono::duration_cast<std::chrono::seconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
    Ticket ticket("T-1", car, spot, entryTime);

    std::cout << "Vehicle plate: " << ticket.vehicle.plate << std::endl;
    std::cout << "Vehicle type: " << vehicleTypeToString(ticket.vehicle.type) << std::endl;
    std::cout << "Assigned spot id: " << ticket.spot.id << std::endl;
    std::cout << "Ticket id: " << ticket.id << std::endl;

    return 0;
}

