import java.util.ArrayList;
import java.util.List;

enum VehicleType { CAR, BIKE, TRUCK }

class Vehicle {
    String plate;
    VehicleType type;
    Vehicle(String plate, VehicleType type) {
        this.plate = plate;
        this.type = type;
    }
    VehicleType getType() { return type; }
}

class Spot {
    int id;
    VehicleType fits;
    boolean free = true;
    Spot(int id, VehicleType fits) {
        this.id = id;
        this.fits = fits;
    }
    void occupy(Vehicle v) { free = false; }
    void free() { free = true; }
}

class Level {
    List<Spot> spots = new ArrayList<>();
}

class Ticket {
    Vehicle vehicle;
    Spot spot;
    Ticket(Vehicle vehicle, Spot spot) {
        this.vehicle = vehicle;
        this.spot = spot;
    }
    Spot getSpot() { return spot; }
}

class PricingService {
    double price(Ticket ticket) {
        return 40.0;   // flat demo rate
    }
}

class ParkingLot {
    private List<Level> levels = new ArrayList<>();
    private PricingService pricing = new PricingService();

    void addLevel(Level level) { levels.add(level); }

    private Spot findFreeSpot(VehicleType type) {
        for (Level level : levels) {
            for (Spot spot : level.spots) {
                if (spot.free && spot.fits == type) {
                    return spot;
                }
            }
        }
        return null;
    }

    public Ticket park(Vehicle vehicle) {
        Spot spot = findFreeSpot(vehicle.getType());
        spot.occupy(vehicle);
        return new Ticket(vehicle, spot);
    }

    public double unpark(Ticket ticket) {
        ticket.getSpot().free();
        return pricing.price(ticket);
    }
}

public class Main {
    public static void main(String[] args) {
        Level level = new Level();
        level.spots.add(new Spot(1, VehicleType.CAR));
        level.spots.add(new Spot(2, VehicleType.CAR));

        ParkingLot lot = new ParkingLot();
        lot.addLevel(level);

        Vehicle car = new Vehicle("KA-01-HH-1234", VehicleType.CAR);
        Ticket ticket = lot.park(car);
        System.out.println("Parked in spot " + ticket.getSpot().id);

        double fee = lot.unpark(ticket);
        System.out.println("Fee due: " + fee);
    }
}

