#include <iostream>
#include <string>
#include <vector>

enum class VehicleType { CAR, BIKE, TRUCK };

class Vehicle {
public:
    std::string plate;
    VehicleType type;
    Vehicle(std::string plate, VehicleType type) : plate(plate), type(type) {}
    VehicleType getType() const { return type; }
};

class Spot {
public:
    int id;
    VehicleType fits;
    bool free;
    Spot(int id, VehicleType fits) : id(id), fits(fits), free(true) {}
    void occupy(const Vehicle& v) { free = false; }
    void release() { free = true; }
};

class Level {
public:
    std::vector<Spot> spots;
};

class Ticket {
public:
    Vehicle vehicle;
    Spot spot;
    Ticket(Vehicle vehicle, Spot spot) : vehicle(vehicle), spot(spot) {}
    Spot& getSpot() { return spot; }
};

class PricingService {
public:
    double price(const Ticket& ticket) {
        return 40.0;   // flat demo rate
    }
};

class ParkingLot {
private:
    std::vector<Level> levels;
    PricingService pricing;

    Spot* findFreeSpot(VehicleType type) {
        for (auto& level : levels) {
            for (auto& spot : level.spots) {
                if (spot.free && spot.fits == type) {
                    return &spot;
                }
            }
        }
        return nullptr;
    }

public:
    void addLevel(const Level& level) { levels.push_back(level); }

    Ticket park(const Vehicle& vehicle) {
        Spot* spot = findFreeSpot(vehicle.getType());
        spot->occupy(vehicle);
        return Ticket(vehicle, *spot);
    }

    double unpark(Ticket& ticket) {
        ticket.getSpot().release();
        return pricing.price(ticket);
    }
};

int main() {
    Level level;
    level.spots.push_back(Spot(1, VehicleType::CAR));
    level.spots.push_back(Spot(2, VehicleType::CAR));

    ParkingLot lot;
    lot.addLevel(level);

    Vehicle car("KA-01-HH-1234", VehicleType::CAR);
    Ticket ticket = lot.park(car);
    std::cout << "Parked in spot " << ticket.getSpot().id << std::endl;

    double fee = lot.unpark(ticket);
    std::cout << "Fee due: " << fee << std::endl;

    return 0;
}

