from enum import Enum
import time
from abc import ABC, abstractmethod


class VehicleType(Enum):
    CAR = "CAR"
    BIKE = "BIKE"
    TRUCK = "TRUCK"


class Vehicle(ABC):
    def __init__(self, plate):
        self.plate = plate

    @abstractmethod
    def type(self):
        pass


class Car(Vehicle):
    def __init__(self, plate):
        super().__init__(plate)

    def type(self):
        return VehicleType.CAR


class Spot:
    def __init__(self, spot_id, fits):
        self.id = spot_id
        self.fits = fits
        self.free = True

    def occupy(self):
        self.free = False

    def release(self):
        self.free = True


class Ticket:
    def __init__(self, vehicle, spot):
        self.vehicle = vehicle
        self.spot = spot
        self.entry_time = int(time.time())


if __name__ == "__main__":
    car = Car("KA-01-HH-1234")
    spot = Spot(7, car.type())
    spot.occupy()

    ticket = Ticket(car, spot)

    print(f"Vehicle is a {ticket.vehicle.type().value}")
    print(f"Occupied spot {ticket.spot.id}")
    print(f"Entry time recorded: {ticket.entry_time > 0}")

