#include <chrono>

enum class VehicleType { CAR, BIKE, TRUCK };

class Vehicle {
public:
    std::string plate;
    Vehicle(std::string plate) : plate(plate) {}
    virtual VehicleType type() = 0;
    virtual ~Vehicle() {}
};

class Car : public Vehicle {
public:
    Car(std::string plate) : Vehicle(plate) {}
    VehicleType type() override { return VehicleType::CAR; }
};

class Spot {
public:
    int id;
    VehicleType fits;
    bool free;
    Spot(int id, VehicleType fits) : id(id), fits(fits), free(true) {}
    void occupy() { free = false; }
    void release() { free = true; }
};

long long now() {
    return std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
}

class Ticket {
public:
    Vehicle* vehicle;
    Spot spot;
    long long entryTime;

    Ticket(Vehicle* vehicle, Spot spot) : vehicle(vehicle), spot(spot), entryTime(now()) {}
};

int main() {
    Car car("KA-01-HH-1234");
    Spot spot(7, car.type());
    spot.occupy();

    Ticket ticket(&car, spot);

    std::cout << "Vehicle is a CAR" << std::endl;
    std::cout << "Occupied spot " << ticket.spot.id << std::endl;
    std::cout << "Entry time recorded: " << (ticket.entryTime > 0) << std::endl;

    return 0;
}

