from enum import Enum


class VehicleType(Enum):
    CAR = "CAR"
    BIKE = "BIKE"
    TRUCK = "TRUCK"


class Vehicle:
    def __init__(self, plate, vehicle_type):
        self.plate = plate
        self.vehicle_type = vehicle_type

    def type(self):
        return self.vehicle_type


class Spot:
    def __init__(self, spot_id, fits):
        self.id = spot_id
        self.fits = fits
        self.free = True

    def occupy(self):
        self.free = False

    def release(self):
        self.free = True


class Level:
    def __init__(self):
        self.spots = []


class Ticket:
    def __init__(self, vehicle, spot):
        self.vehicle = vehicle
        self.spot = spot


class PricingStrategy:
    def price(self, ticket):
        raise NotImplementedError


class HourlyPricing(PricingStrategy):
    def price(self, ticket):
        return 30.0   # flat hourly demo rate


class ParkingLot:
    def __init__(self, pricing):
        self.levels = []
        self.pricing = pricing

    def add_level(self, level):
        self.levels.append(level)

    def _find_spot(self, vehicle_type):
        for level in self.levels:
            for spot in level.spots:
                if spot.free and spot.fits == vehicle_type:
                    return spot
        return None

    def park(self, vehicle):
        spot = self._find_spot(vehicle.type())
        spot.occupy()
        return Ticket(vehicle, spot)

    def unpark(self, ticket):
        ticket.spot.release()
        return self.pricing.price(ticket)


if __name__ == "__main__":
    level = Level()
    level.spots.append(Spot(1, VehicleType.CAR))

    lot = ParkingLot(HourlyPricing())
    lot.add_level(level)

    car = Vehicle("KA-01-HH-1234", VehicleType.CAR)
    ticket = lot.park(car)
    print(f"Parked, spot free: {ticket.spot.free}")

    fee = lot.unpark(ticket)
    print(f"Weekend follow up: swap in a WeekendPricing strategy, fee due: {fee}")

