import java.util.ArrayList;
import java.util.List;

enum VehicleType { CAR, BIKE, TRUCK }

class Vehicle {
    String plate;
    VehicleType type;
    Vehicle(String plate, VehicleType type) {
        this.plate = plate;
        this.type = type;
    }
    VehicleType type() { return type; }
}

class Spot {
    int id;
    VehicleType fits;
    boolean free = true;
    Spot(int id, VehicleType fits) {
        this.id = id;
        this.fits = fits;
    }
    void occupy() { free = false; }
    void release() { free = true; }
}

class Level {
    List<Spot> spots = new ArrayList<>();
}

class Ticket {
    Vehicle v;
    Spot spot;
    Ticket(Vehicle v, Spot spot) {
        this.v = v;
        this.spot = spot;
    }
}

interface PricingStrategy {
    double price(Ticket t);
}

class HourlyPricing implements PricingStrategy {
    public double price(Ticket t) {
        return 30.0;   // flat hourly demo rate
    }
}

class ParkingLot {
    List<Level> levels = new ArrayList<>();
    PricingStrategy pricing;

    ParkingLot(PricingStrategy pricing) {
        this.pricing = pricing;
    }

    void addLevel(Level level) { levels.add(level); }

    private Spot findSpot(VehicleType type) {
        for (Level level : levels) {
            for (Spot spot : level.spots) {
                if (spot.free && spot.fits == type) {
                    return spot;
                }
            }
        }
        return null;
    }

    Ticket park(Vehicle v) {
        Spot spot = findSpot(v.type());
        spot.occupy();
        return new Ticket(v, spot);
    }

    double unpark(Ticket t) {
        t.spot.release();
        return pricing.price(t);
    }
}

public class Main {
    public static void main(String[] args) {
        Level level = new Level();
        level.spots.add(new Spot(1, VehicleType.CAR));

        ParkingLot lot = new ParkingLot(new HourlyPricing());
        lot.addLevel(level);

        Vehicle car = new Vehicle("KA-01-HH-1234", VehicleType.CAR);
        Ticket ticket = lot.park(car);
        System.out.println("Parked, spot free: " + ticket.spot.free);

        double fee = lot.unpark(ticket);
        System.out.println("Weekend follow up: swap in a WeekendPricing strategy, fee due: " + fee);
    }
}

