#include <iostream>
#include <string>
#include <vector>
#include <memory>

enum class VehicleType { CAR, BIKE, TRUCK };

class Vehicle {
public:
    std::string plate;
    VehicleType vehicleType;
    Vehicle(std::string plate, VehicleType vehicleType) : plate(plate), vehicleType(vehicleType) {}
    VehicleType type() const { return vehicleType; }
};

class Spot {
public:
    int id;
    VehicleType fits;
    bool free;
    Spot(int id, VehicleType fits) : id(id), fits(fits), free(true) {}
    void occupy() { free = false; }
    void release() { free = true; }
};

class Level {
public:
    std::vector<Spot> spots;
};

class Ticket {
public:
    Vehicle v;
    Spot spot;
    Ticket(Vehicle v, Spot spot) : v(v), spot(spot) {}
};

class PricingStrategy {
public:
    virtual double price(const Ticket& t) = 0;
    virtual ~PricingStrategy() {}
};

class HourlyPricing : public PricingStrategy {
public:
    double price(const Ticket& t) override {
        return 30.0;   // flat hourly demo rate
    }
};

class ParkingLot {
public:
    std::vector<Level> levels;
    std::shared_ptr<PricingStrategy> pricing;

    ParkingLot(std::shared_ptr<PricingStrategy> pricing) : pricing(pricing) {}

    void addLevel(const Level& level) { levels.push_back(level); }

    Spot* findSpot(VehicleType type) {
        for (auto& level : levels) {
            for (auto& spot : level.spots) {
                if (spot.free && spot.fits == type) {
                    return &spot;
                }
            }
        }
        return nullptr;
    }

    Ticket park(const Vehicle& v) {
        Spot* spot = findSpot(v.type());
        spot->occupy();
        return Ticket(v, *spot);
    }

    double unpark(Ticket& t) {
        t.spot.release();
        return pricing->price(t);
    }
};

int main() {
    Level level;
    level.spots.push_back(Spot(1, VehicleType::CAR));

    ParkingLot lot(std::make_shared<HourlyPricing>());
    lot.addLevel(level);

    Vehicle car("KA-01-HH-1234", VehicleType::CAR);
    Ticket ticket = lot.park(car);
    std::cout << "Parked, spot free: " << ticket.spot.free << std::endl;

    double fee = lot.unpark(ticket);
    std::cout << "Weekend follow up: swap in a WeekendPricing strategy, fee due: " << fee << std::endl;

    return 0;
}
